"use client";

import { useCallback, useMemo, useState } from "react";
import { Drawer as BaseDrawer } from "@base-ui/react/drawer";

import { useResolvedDirection } from "../hooks/use-direction";

import {
  type DrawerSide,
  type DrawerSnapPoint,
  type DrawerLabels,
  defaultDrawerLabels,
  drawerSnapPresets,
  type DrawerProps,
  type BaseRootProps,
  HALF_ABOVE_PEEK,
  FULL_GAP,
  type ResolvedPresets,
  toBaseSnapPoint,
  toPx,
  useViewportHeight,
  type DrawerContextValue,
  DrawerContext,
  swipeDirections,
} from "./parts/model";

export {
  type DrawerSide,
  type DrawerSideProp,
  type DrawerSnapPreset,
  type DrawerSnapPoint,
  type DrawerLabels,
  type DrawerLabelsInput,
  defaultDrawerLabels,
  drawerSnapPresets,
  type DrawerProps,
} from "./parts/model";
export { type DrawerContentProps, DrawerContent } from "./parts/content";
export {
  DrawerHandle,
  DrawerHeader,
  DrawerTitle,
  DrawerDescription,
  DrawerBody,
  DrawerFooter,
  DrawerSwipeArea,
  type DrawerTriggerProps,
  type DrawerCloseProps,
  type DrawerHandleProps,
  type DrawerHeaderProps,
  type DrawerTitleProps,
  type DrawerDescriptionProps,
  type DrawerBodyProps,
  type DrawerFooterProps,
  type DrawerSwipeAreaProps,
} from "./parts/parts";

/* ---------- Root ---------- */

/**
 * Drawer / sheet: a strong-glass panel that slides in from an edge of the screen. Use it for filters, details and menus on phones and for side panels on desktop; use `Dialog` for a centred modal and `SideDrawer`
 * for a record detail or form panel. This is the root: it holds the open state (`open`, `defaultOpen`, `onOpenChange`) and the snap point. Compose `DrawerTrigger`, `DrawerContent`, `DrawerHeader`, `DrawerTitle`,
 * `DrawerDescription`, `DrawerBody`, `DrawerFooter` and `DrawerClose`.
 *
 * - Bottom sheet (`side="bottom"`) with a drag handle, swipe-to-dismiss and optional snap points ("peek" / "half" / "full", or your own heights; `snapPoints`, `snapPoint`, `defaultSnapPoint`, `onSnapPointChange`).
 *   The handle is a real button when there are snap points: click / Enter cycles them, ArrowUp / ArrowDown step through them, and it tells screen readers the current height.
 * - "peek" is measured from the content: the handle, the header and the first row of the body. "half" never drops below peek plus a row, so a short (landscape) screen still shows content.
 * - Side sheets (`left` / `right`) and a top sheet, attached to the edge or floating (`inset` on `DrawerContent`).
 * - `modal` (default true) traps focus; `labels` translates every string.
 * - Safe-area insets (notches, home indicator) are padded on every side that touches the screen edge.
 *
 * Keyboard: Enter or Space on the trigger opens it; focus moves in and is trapped (modal), Escape and an outside press close it, and focus returns to the trigger.
 * Accessibility: `role="dialog"` named by `DrawerTitle`; the page behind is inert and scroll-locked; the × button has an `aria-label` and a 44px target; the handle reads the current height.
 * Glass and motion: the `glass-3` popup itself slides (never a wrapper, so the blur never drops out). Enter springs (`--sheen-ease-smooth`); a button / Escape close is shorter and eases in with no overshoot; a swipe-dismiss keeps the finger's
 * momentum (ease-out, scaled by swipe speed). Reduced motion (OS or `[data-motion="reduced"]`): no sliding, the panel fades in place; dragging still follows the finger (direct manipulation).
 *
 * Built on Base UI Drawer: https://base-ui.com/react/components/drawer
 *
 * @example
 * ```tsx
 * import { Button, Drawer, DrawerBody, DrawerContent, DrawerHeader, DrawerTitle, DrawerTrigger } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <Drawer snapPoints={["peek", "half", "full"]}>
 *       <DrawerTrigger render={<Button>Filters</Button>} />
 *       <DrawerContent>
 *         <DrawerHeader><DrawerTitle>Filters</DrawerTitle></DrawerHeader>
 *         <DrawerBody>...</DrawerBody>
 *       </DrawerContent>
 *     </Drawer>
 *   );
 * }
 * ```
 *
 * @see /overlays/drawer
 */
export function Drawer({
  side: sideProp = "bottom",
  snapPoints,
  snapPoint: snapPointProp,
  defaultSnapPoint,
  onSnapPointChange,
  onOpenChange,
  labels: labelsProp,
  modal = true,
  children,
  ...props
}: DrawerProps) {
  const dir = useResolvedDirection();
  const side: DrawerSide =
    sideProp === "start"
      ? dir === "rtl"
        ? "right"
        : "left"
      : sideProp === "end"
        ? dir === "rtl"
          ? "left"
          : "right"
        : sideProp;
  const usesSnapPoints = side === "bottom" && snapPoints !== undefined && snapPoints.length > 0;
  const initialSnap = defaultSnapPoint !== undefined ? defaultSnapPoint : (snapPoints?.[0] ?? null);
  const [uncontrolledSnap, setUncontrolledSnap] = useState<DrawerSnapPoint | null>(initialSnap);
  const controlled = snapPointProp !== undefined;
  const snapPoint = controlled ? snapPointProp : uncontrolledSnap;

  const labels = useMemo<DrawerLabels>(
    () => ({
      ...defaultDrawerLabels,
      ...labelsProp,
      snapPoints: { ...defaultDrawerLabels.snapPoints, ...labelsProp?.snapPoints },
    }),
    [labelsProp],
  );

  // Keyed by value, so an inline array (snapPoints={["peek", "half"]}) doesn't hand Base UI a new
  // array on every render.
  const snapKey = usesSnapPoints ? JSON.stringify(snapPoints) : "[]";
  const stableSnapPoints = useMemo(() => JSON.parse(snapKey) as DrawerSnapPoint[], [snapKey]);

  // Content-aware presets: "peek" fits the header and a first row, "half" stays above it.
  const viewportHeight = useViewportHeight(usesSnapPoints);
  const [peekHeight, setPeekHeightState] = useState<number | null>(null);
  const setPeekHeight = useCallback((px: number) => {
    setPeekHeightState((previous) => (previous !== null && Math.abs(previous - px) < 2 ? previous : px));
  }, []);

  const presets = useMemo<ResolvedPresets>(() => {
    if (viewportHeight <= 0) return drawerSnapPresets;
    const peek = peekHeight ?? toPx(drawerSnapPresets.peek, viewportHeight);
    const half = Math.max(viewportHeight * 0.5, peek + HALF_ABOVE_PEEK);
    return {
      peek: peekHeight === null ? drawerSnapPresets.peek : `${Math.round(peekHeight)}px`,
      half: half > viewportHeight * 0.5 + 0.5 ? `${Math.round(half)}px` : 0.5,
      full: 1,
    };
  }, [peekHeight, viewportHeight]);

  const baseSnapPoints = useMemo(
    () => (stableSnapPoints.length > 0 ? stableSnapPoints.map((point) => toBaseSnapPoint(point, presets)) : undefined),
    [stableSnapPoints, presets],
  );

  /** Px height of a snap point, capped like Base UI caps it (the sheet can't be taller than the screen). */
  const heightOf = useCallback(
    (point: DrawerSnapPoint) => {
      const viewport = viewportHeight || (typeof window === "undefined" ? 0 : window.innerHeight);
      return Math.min(toPx(toBaseSnapPoint(point, presets), viewport), Math.max(0, viewport - FULL_GAP));
    },
    [presets, viewportHeight],
  );

  // Smallest first, whatever order (and units) they were given in. Points that end up the same
  // height (e.g. "half" on a short landscape screen) collapse into one, like Base UI does.
  const orderedSnapPoints = useMemo(() => {
    const entries = stableSnapPoints
      .map((point, order) => ({ point, order, height: heightOf(point) }))
      .sort((a, b) => a.height - b.height || a.order - b.order);
    return entries
      .filter((entry, index) => {
        const next = entries[index + 1];
        return !next || Math.abs(next.height - entry.height) > 1;
      })
      .map((entry) => entry.point);
  }, [stableSnapPoints, heightOf]);

  const snapIndex = useMemo(() => {
    if (snapPoint === null || orderedSnapPoints.length === 0) return 0;
    const exact = orderedSnapPoints.findIndex((point) => Object.is(point, snapPoint));
    if (exact !== -1) return exact;
    const target = heightOf(snapPoint);
    let best = 0;
    orderedSnapPoints.forEach((point, index) => {
      const bestPoint = orderedSnapPoints[best];
      if (bestPoint !== undefined && Math.abs(heightOf(point) - target) < Math.abs(heightOf(bestPoint) - target))
        best = index;
    });
    return best;
  }, [snapPoint, orderedSnapPoints, heightOf]);

  /** Base UI reports raw values ("182px", 0.5): hand back the name the caller used. */
  const fromBase = useCallback(
    (value: number | string | null): DrawerSnapPoint | null => {
      if (value === null) return value;
      const exact = stableSnapPoints.find((point) => Object.is(toBaseSnapPoint(point, presets), value));
      if (exact !== undefined) return exact;
      // The presets were re-measured in between: pick the nearest height.
      const viewport = viewportHeight || window.innerHeight;
      const target = toPx(value, viewport);
      let best: DrawerSnapPoint | undefined;
      for (const point of stableSnapPoints) {
        if (best === undefined || Math.abs(heightOf(point) - target) < Math.abs(heightOf(best) - target)) best = point;
      }
      return best ?? value;
    },
    [stableSnapPoints, presets, viewportHeight, heightOf],
  );

  const setSnapPoint = useCallback(
    (value: DrawerSnapPoint | null, details?: BaseDrawer.Root.SnapPointChangeEventDetails) => {
      if (!controlled) setUncontrolledSnap(value);
      onSnapPointChange?.(value, details);
    },
    [controlled, onSnapPointChange],
  );

  const context = useMemo<DrawerContextValue>(
    () => ({ side, modal, labels, orderedSnapPoints, snapIndex, snapPoint, setSnapPoint, setPeekHeight }),
    [side, modal, labels, orderedSnapPoints, snapIndex, snapPoint, setSnapPoint, setPeekHeight],
  );

  const snapProps: Partial<BaseRootProps> = usesSnapPoints
    ? {
        snapPoints: baseSnapPoints,
        snapPoint: snapPoint === null ? null : toBaseSnapPoint(snapPoint, presets),
        onSnapPointChange: (value, details) => setSnapPoint(fromBase(value), details),
      }
    : {};

  return (
    <DrawerContext value={context}>
      <BaseDrawer.Root
        swipeDirection={swipeDirections[side]}
        modal={modal}
        {...snapProps}
        onOpenChange={(open, details) => {
          // Every opening starts from the default snap point, not where it was last left.
          if (open && usesSnapPoints && !controlled) setUncontrolledSnap(initialSnap);
          onOpenChange?.(open, details);
        }}
        {...props}
      >
        {children}
      </BaseDrawer.Root>
    </DrawerContext>
  );
}

/**
 * The element that opens a `Drawer` (a `<button>` by default; use `render={<Button />}` for a SheenUI button). Pass a `handle` from `createDrawerHandle()` for a trigger outside `<Drawer>`.
 *
 * Keyboard: Enter or Space opens the drawer. Accessibility: `aria-haspopup="dialog"` and `aria-expanded`. Glass and motion: none of its own.
 *
 * @example
 * ```tsx
 * import { Button, DrawerTrigger } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <DrawerTrigger render={<Button variant="glass">Open</Button>} />
 *   );
 * }
 * ```
 *
 * @see /overlays/drawer
 */
export const DrawerTrigger = BaseDrawer.Trigger;
/**
 * A button inside the drawer that closes it (a "Done" or "Cancel" action in `DrawerFooter`).
 *
 * Keyboard: Enter or Space closes the drawer and focus returns to the trigger. Accessibility: a native button, so give it visible text or an `aria-label`. Glass and motion: none of its own.
 *
 * @example
 * ```tsx
 * import { Button, DrawerClose, DrawerFooter } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <DrawerFooter>
 *       <DrawerClose render={<Button variant="ghost">Cancel</Button>} />
 *     </DrawerFooter>
 *   );
 * }
 * ```
 *
 * @see /overlays/drawer
 */
export const DrawerClose = BaseDrawer.Close;
/** Connects a Drawer to triggers rendered elsewhere: `<Drawer handle={h}>` + `<DrawerTrigger handle={h}>`. */
export const createDrawerHandle = BaseDrawer.createHandle;

"use client";

import { useEffect, useRef, useState, type ComponentProps, type ReactNode } from "react";
import { Drawer as BaseDrawer } from "@base-ui/react/drawer";

import { cn, classNameWith } from "../../lib/cn";
import { useMergedRef } from "../../lib/form";
import { PEEK_ROW_MAX, useDrawerContext } from "./model";
import { DrawerHandle } from "./parts";

/* ---------- Content ---------- */

/**
 * Props of `DrawerContent`: the Base UI `Drawer.Popup` props plus SheenUI's own options, each
 * documented on its field.
 */
export type DrawerContentProps = ComponentProps<typeof BaseDrawer.Popup> & {
  /** Show the × button in the top corner. Default true. */
  showClose?: boolean;
  /** Show the drag handle. Defaults to on for bottom and top sheets. */
  handle?: boolean;
  /** Float the panel off the edges (rounded on every side) instead of attaching it to the edge. Default false. */
  inset?: boolean;
  /**
   * Keep focused fields above the on-screen keyboard (bottom sheets with forms).
   * Uses Base UI's Drawer.VirtualKeyboardProvider. Default true.
   */
  keyboardAware?: boolean;
  /** Where to portal the drawer (defaults to <body>). */
  container?: ComponentProps<typeof BaseDrawer.Portal>["container"];
  /** Adds extra classes to the full-screen positioning layer. */
  viewportClassName?: string;
  /** Class for the dimmed scrim behind a modal drawer. */
  backdropClassName?: string;
  /** The sheet's content: usually `DrawerHeader`, `DrawerBody` and `DrawerFooter`. */
  children?: ReactNode;
};

/*
 * Spring in; a shorter, overshoot-free ease-in out. Opacity only matters under reduced motion.
 * The exit of a large panel is derived from the exit token (x1.5, overridable with
 * --sheen-duration-exit-panel): still well under the enter spring, and never overshooting.
 */
/** The transition classes of the drawer popup: a smooth enter and a shorter, non-overshooting exit. @internal */
export const popupMotion = cn(
  "[transition:transform_var(--sheen-duration-smooth)_var(--sheen-ease-smooth),scale_var(--sheen-duration-smooth)_var(--sheen-ease-smooth),opacity_var(--sheen-duration-base)_var(--sheen-ease-out)]",
  "data-ending-style:[transition:transform_var(--sheen-duration-exit-panel,calc(var(--sheen-duration-exit)*1.5))_var(--sheen-ease-exit),opacity_var(--sheen-duration-exit)_var(--sheen-ease-exit)]",
  // Released by a swipe: keep the finger's momentum, faster for a faster flick.
  "data-ending-style:data-swipe-dismiss:[transition:transform_calc(var(--drawer-swipe-strength)*var(--sheen-duration-slow))_var(--sheen-ease-out),opacity_var(--sheen-duration-exit)_var(--sheen-ease-exit)]",
  // Reduced motion (OS setting or in-app toggle): nothing slides, the panel fades in place.
  "motion-reduced:data-starting-style:opacity-0 motion-reduced:data-ending-style:opacity-0",
);

/*
 * Per side: where the panel sits, how it follows the finger, and where it enters from.
 * "Bleed": a strip of the same surface just past the screen edge (::after), so a drag past
 * the open position or the spring's tiny overshoot never shows a gap.
 */
/** The popup classes of an edge-attached drawer, per side. @internal */
export const attached = {
  bottom: cn(
    "w-full max-w-2xl max-h-[calc(100dvh-var(--sheen-drawer-gap))] rounded-t-sheen-xl border-b-0",
    "pr-[env(safe-area-inset-right)] pl-[env(safe-area-inset-left)]",
    "[transform:translateY(calc(var(--drawer-snap-point-offset)+var(--drawer-swipe-movement-y)))]",
    "motion-ok:data-starting-style:[transform:translateY(calc(100%+2px))] motion-ok:data-ending-style:[transform:translateY(calc(100%+2px))]",
    "after:pointer-events-none after:absolute after:-inset-x-px after:top-full after:h-16 after:bg-[inherit] after:content-['']",
  ),
  top: cn(
    "w-full max-w-2xl max-h-[calc(100dvh-var(--sheen-drawer-gap))] rounded-b-sheen-xl border-t-0",
    "pt-[env(safe-area-inset-top)] pr-[env(safe-area-inset-right)] pl-[env(safe-area-inset-left)]",
    "[transform:translateY(var(--drawer-swipe-movement-y))]",
    "motion-ok:data-starting-style:[transform:translateY(calc(-100%-2px))] motion-ok:data-ending-style:[transform:translateY(calc(-100%-2px))]",
    "after:pointer-events-none after:absolute after:-inset-x-px after:bottom-full after:h-16 after:bg-[inherit] after:content-['']",
  ),
  left: cn(
    "h-full w-[min(22rem,calc(100vw-3rem))] rounded-r-sheen-xl border-l-0",
    "pt-[env(safe-area-inset-top)] pb-[env(safe-area-inset-bottom)] pl-[env(safe-area-inset-left)]",
    "[transform:translateX(var(--drawer-swipe-movement-x))]",
    "motion-ok:data-starting-style:[transform:translateX(calc(-100%-2px))] motion-ok:data-ending-style:[transform:translateX(calc(-100%-2px))]",
    "after:pointer-events-none after:absolute after:-inset-y-px after:right-full after:w-16 after:bg-[inherit] after:content-['']",
  ),
  right: cn(
    "h-full w-[min(22rem,calc(100vw-3rem))] rounded-l-sheen-xl border-r-0",
    "pt-[env(safe-area-inset-top)] pr-[env(safe-area-inset-right)] pb-[env(safe-area-inset-bottom)]",
    "[transform:translateX(var(--drawer-swipe-movement-x))]",
    "motion-ok:data-starting-style:[transform:translateX(calc(100%+2px))] motion-ok:data-ending-style:[transform:translateX(calc(100%+2px))]",
    "after:pointer-events-none after:absolute after:-inset-y-px after:left-full after:w-16 after:bg-[inherit] after:content-['']",
  ),
} as const;

/* Floating: rounded all round, held off the edges (and out of the safe areas) by the viewport's padding. */
/** The popup classes of a floating drawer, per side: rounded and held off the edges. @internal */
export const floating = {
  bottom: cn(
    "w-full max-w-2xl max-h-[calc(100dvh-var(--sheen-drawer-gap)-0.5rem)] rounded-sheen-xl",
    "[transform:translateY(calc(var(--drawer-snap-point-offset)+var(--drawer-swipe-movement-y)))]",
    "motion-ok:data-starting-style:[transform:translateY(calc(100%+var(--sheen-drawer-inset-bottom)+2px))] motion-ok:data-ending-style:[transform:translateY(calc(100%+var(--sheen-drawer-inset-bottom)+2px))]",
  ),
  top: cn(
    "w-full max-w-2xl max-h-[calc(100dvh-var(--sheen-drawer-gap)-0.5rem)] rounded-sheen-xl",
    "[transform:translateY(var(--drawer-swipe-movement-y))]",
    "motion-ok:data-starting-style:[transform:translateY(calc(-100%-var(--sheen-drawer-inset-top)-2px))] motion-ok:data-ending-style:[transform:translateY(calc(-100%-var(--sheen-drawer-inset-top)-2px))]",
  ),
  left: cn(
    "h-full w-[min(22rem,calc(100vw-3rem))] rounded-sheen-xl",
    "[transform:translateX(var(--drawer-swipe-movement-x))]",
    "motion-ok:data-starting-style:[transform:translateX(calc(-100%-var(--sheen-drawer-inset-left)-2px))] motion-ok:data-ending-style:[transform:translateX(calc(-100%-var(--sheen-drawer-inset-left)-2px))]",
  ),
  right: cn(
    "h-full w-[min(22rem,calc(100vw-3rem))] rounded-sheen-xl",
    "[transform:translateX(var(--drawer-swipe-movement-x))]",
    "motion-ok:data-starting-style:[transform:translateX(calc(100%+var(--sheen-drawer-inset-right)+2px))] motion-ok:data-ending-style:[transform:translateX(calc(100%+var(--sheen-drawer-inset-right)+2px))]",
  ),
} as const;

/** The viewport anchoring classes of each drawer side. @internal */
export const viewportSide = {
  bottom: "items-end justify-center",
  top: "items-start justify-center",
  left: "items-stretch justify-start",
  right: "items-stretch justify-end",
} as const;

/** The first "row" of the body: step into lists and wrappers until something row-sized. */
export function firstRow(body: HTMLElement): Element | null {
  let element = body.firstElementChild;
  while (element?.firstElementChild && element.getBoundingClientRect().height > PEEK_ROW_MAX) {
    element = element.firstElementChild;
  }
  return element;
}

/** Height that shows the handle, the header and the first row of the body (plus the home-indicator area). */
export function measurePeek(popup: HTMLElement): number | null {
  // Scaled back behind a nested sheet: distances are off until it returns.
  if (popup.hasAttribute("data-nested-drawer-open")) return null;
  const top = popup.getBoundingClientRect().top;
  const safeArea = popup.querySelector<HTMLElement>(':scope > [data-slot="drawer-safe-area"]')?.offsetHeight ?? 0;
  const body = popup.querySelector<HTMLElement>(':scope > [data-slot="drawer-body"]');
  if (!body) {
    const header = popup.querySelector(':scope > [data-slot="drawer-header"]');
    return header ? Math.ceil(header.getBoundingClientRect().bottom - top + safeArea) : null;
  }
  const bodyTop = body.getBoundingClientRect().top;
  const row = firstRow(body);
  const rowBottom = row ? row.getBoundingClientRect().bottom - bodyTop + body.scrollTop : 0;
  return Math.ceil(bodyTop - top + Math.min(Math.max(0, rowBottom), PEEK_ROW_MAX) + 4 + safeArea);
}

/** Whether a focused element sits (partly) below the visible part of a snapped sheet. */
export function isBelowFold(element: HTMLElement) {
  const rect = element.getBoundingClientRect();
  const visibleBottom = window.visualViewport?.height ?? window.innerHeight;
  if (rect.top >= visibleBottom - 8 || rect.bottom > visibleBottom + 1) return true;
  // The scroll body itself: only when too little of it is on screen to scroll through.
  if (element.getAttribute("data-slot") === "drawer-body") return element.clientHeight < 48;
  const body = element.closest<HTMLElement>('[data-slot="drawer-body"]');
  return body ? rect.bottom > body.getBoundingClientRect().bottom + 1 : false;
}

/**
 * The glass panel of a `Drawer`, portalled to the end of the body with a dimmed scrim (for a modal drawer). `showClose` toggles the × button, `handle` the drag handle (on for bottom and top sheets), `inset` floats the panel off the edges,
 * `keyboardAware` keeps focused fields above the on-screen keyboard (bottom sheets with forms), `container` chooses where it portals, and `viewportClassName` / `backdropClassName` style the positioning layer and the scrim.
 * Every other prop goes to the Base UI popup.
 *
 * Keyboard: see `Drawer` (focus trapped, Escape closes). Accessibility: `role="dialog"`; label it with `DrawerTitle`. Glass and motion: `glass-3` panel that slides from its edge; reduced transparency and forced colors give it a solid surface; see `Drawer` for the motion rules.
 *
 * @example
 * ```tsx
 * import { DrawerContent, DrawerHeader, DrawerTitle } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <DrawerContent inset showClose={false}>
 *       <DrawerHeader><DrawerTitle>Notifications</DrawerTitle></DrawerHeader>
 *     </DrawerContent>
 *   );
 * }
 * ```
 *
 * @see /overlays/drawer
 */
export function DrawerContent({
  className,
  children,
  showClose = true,
  handle,
  inset = false,
  keyboardAware = true,
  container,
  viewportClassName,
  backdropClassName,
  ref,
  onFocus,
  onPointerDownCapture,
  onKeyDownCapture,
  ...props
}: DrawerContentProps) {
  const { side, modal, labels, orderedSnapPoints, snapPoint, setSnapPoint, setPeekHeight } =
    useDrawerContext("DrawerContent");
  const vertical = side === "bottom" || side === "top";
  const showHandle = handle ?? vertical;
  const snaps = orderedSnapPoints.length > 0;
  const [popup, setPopup] = useState<HTMLDivElement | null>(null);
  const popupRef = useMergedRef(setPopup, ref);
  /** The last input was a pointer press (until a key is pressed). */
  const pointerInput = useRef(false);

  // Measure "peek" (handle + header + first row) while the sheet is open.
  useEffect(() => {
    if (!snaps || !popup || typeof ResizeObserver === "undefined") return;
    const measure = () => {
      const height = measurePeek(popup);
      if (height !== null && height > 0) setPeekHeight(height);
    };
    const resize = new ResizeObserver(measure);
    const observeAll = () => {
      resize.disconnect();
      resize.observe(popup);
      for (const child of Array.from(popup.children)) resize.observe(child);
      const row = popup.querySelector<HTMLElement>(':scope > [data-slot="drawer-body"]');
      const first = row ? firstRow(row) : null;
      if (first) resize.observe(first);
      measure();
    };
    const mutations = new MutationObserver(observeAll);
    mutations.observe(popup, { childList: true });
    observeAll();
    return () => {
      resize.disconnect();
      mutations.disconnect();
    };
  }, [snaps, popup, setPeekHeight]);

  /*
   * A snapped sheet hides part of its content below the screen edge. When KEYBOARD focus moves
   * to something down there, open the sheet fully so the focused control is visible. A click or
   * tap never changes the height (the person can already see what they pressed).
   */
  function handleFocus(event: Parameters<NonNullable<DrawerContentProps["onFocus"]>>[0]) {
    onFocus?.(event);
    if (!snaps || pointerInput.current || event.target === event.currentTarget) return;
    const tallest = orderedSnapPoints[orderedSnapPoints.length - 1];
    if (tallest === undefined || Object.is(snapPoint, tallest)) return;
    const target = event.target;
    const sheet = event.currentTarget;
    // A frame later: the browser has scrolled the focused element into view inside the body. While
    // the sheet is still sliding in (or out) everything is below the screen edge, so wait until it
    // has stopped moving before judging (focus on the handle right after opening must not expand it).
    let frames = 0;
    const check = () => {
      if (document.activeElement !== target) return;
      const moving =
        sheet.hasAttribute("data-starting-style") ||
        sheet.hasAttribute("data-ending-style") ||
        sheet.getAnimations().length > 0;
      if (moving && frames++ < 90) {
        requestAnimationFrame(check);
        return;
      }
      if (isBelowFold(target)) setSnapPoint(tallest);
    };
    requestAnimationFrame(check);
  }

  const portal = (
    <BaseDrawer.Portal container={container}>
      {modal !== false && (
        <BaseDrawer.Backdrop
          className={cn(
            "fixed inset-0 z-50 min-h-dvh bg-sheen-scrim",
            // Lightens as the sheet is dragged away. With snap points Base UI reports full progress
            // below the tallest point, so keep a lighter dim there instead of none.
            snaps
              ? "opacity-[calc(1-0.6*var(--drawer-swipe-progress))]"
              : "opacity-[calc(1-var(--drawer-swipe-progress))]",
            "transition-opacity duration-(--sheen-duration-slow) ease-sheen-out data-swiping:duration-0",
            "data-starting-style:opacity-0 data-ending-style:opacity-0 data-ending-style:duration-[var(--sheen-duration-exit-panel,calc(var(--sheen-duration-exit)*1.5))] data-ending-style:ease-sheen-exit",
            // iOS Safari: a fixed full-height layer jumps with the toolbar; absolute does not.
            "supports-[-webkit-touch-callout:none]:absolute",
            "forced-colors:hidden",
            backdropClassName,
          )}
        />
      )}
      <BaseDrawer.Viewport
        className={cn(
          "fixed inset-0 z-50 flex",
          // Room kept above a bottom sheet (and below a top sheet), clear of the notch / status bar.
          "[--sheen-drawer-gap:max(1.5rem,calc(env(safe-area-inset-top)+0.75rem))]",
          viewportSide[side],
          inset && [
            "[--sheen-drawer-inset-top:max(0.5rem,env(safe-area-inset-top))] [--sheen-drawer-inset-right:max(0.5rem,env(safe-area-inset-right))]",
            "[--sheen-drawer-inset-bottom:max(0.5rem,env(safe-area-inset-bottom))] [--sheen-drawer-inset-left:max(0.5rem,env(safe-area-inset-left))]",
            "pt-(--sheen-drawer-inset-top) pr-(--sheen-drawer-inset-right) pb-(--sheen-drawer-inset-bottom) pl-(--sheen-drawer-inset-left)",
          ],
          // Non-modal: the page behind stays usable.
          modal === false && "pointer-events-none",
          viewportClassName,
        )}
      >
        <BaseDrawer.Popup
          ref={popupRef}
          data-slot="drawer-content"
          data-side={side}
          data-inset={inset ? "" : undefined}
          onFocus={handleFocus}
          onPointerDownCapture={(event) => {
            pointerInput.current = true;
            onPointerDownCapture?.(event);
          }}
          onKeyDownCapture={(event) => {
            pointerInput.current = false;
            onKeyDownCapture?.(event);
          }}
          className={classNameWith(className, (extra) =>
            cn(
              "glass-3 group/drawer pointer-events-auto relative flex min-h-0 flex-col text-sheen-fg outline-none",
              "touch-none",
              inset ? floating[side] : attached[side],
              side === "bottom" && !inset && !snaps && "pb-[env(safe-area-inset-bottom)]",
              snaps &&
                (inset
                  ? "h-[calc(100dvh-var(--sheen-drawer-gap)-0.5rem)] [padding-bottom:max(0px,calc(var(--drawer-snap-point-offset)+var(--drawer-swipe-movement-y)))]"
                  : "h-[calc(100dvh-var(--sheen-drawer-gap))] [padding-bottom:max(env(safe-area-inset-bottom),calc(var(--drawer-snap-point-offset)+var(--drawer-swipe-movement-y)))]"),
              popupMotion,
              side === "bottom" &&
                "origin-top motion-ok:data-nested-drawer-open:scale-[calc(1-0.05*var(--nested-drawers))]",
              "data-swiping:select-none",
              extra,
            ),
          )}
          {...props}
        >
          {showHandle && side !== "top" && <DrawerHandle />}
          {children}
          {showHandle && side === "top" && <DrawerHandle />}
          {/* Measures the home-indicator area, so "peek" keeps its first row above it. */}
          {snaps && (
            <span
              aria-hidden
              data-slot="drawer-safe-area"
              className="pointer-events-none invisible absolute bottom-0 left-0 h-[env(safe-area-inset-bottom)] w-px"
            />
          )}
          {/* Dims this sheet while a nested one is on top of it. */}
          <span
            aria-hidden
            className="pointer-events-none absolute inset-0 z-10 rounded-[inherit] bg-sheen-scrim opacity-0 transition-opacity duration-(--sheen-duration-base) group-data-nested-drawer-open/drawer:opacity-100"
          />
          {showClose && (
            <BaseDrawer.Close
              aria-label={labels.close}
              className={cn(
                "absolute top-3 end-3 z-20 flex size-9 items-center justify-center rounded-sheen-full text-sheen-fg-muted",
                side === "top" && "top-[calc(env(safe-area-inset-top)+0.75rem)]",
                // The close button sits at the logical end; only the physical outer edge needs the notch inset.
                side === "right" &&
                  !inset &&
                  "end-[calc(env(safe-area-inset-right)+0.75rem)] top-[calc(env(safe-area-inset-top)+0.75rem)] rtl:end-3",
                side === "left" &&
                  !inset &&
                  "top-[calc(env(safe-area-inset-top)+0.75rem)] rtl:end-[calc(env(safe-area-inset-left)+0.75rem)]",
                "transition-colors duration-(--sheen-duration-fast) hover:bg-sheen-hover hover:text-sheen-fg",
                "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sheen-focus",
                // 44 × 44 hit area on touch screens.
                "any-pointer-coarse:after:absolute any-pointer-coarse:after:-inset-1",
                "forced-colors:border forced-colors:border-[ButtonText]",
              )}
            >
              <svg
                aria-hidden
                viewBox="0 0 24 24"
                className="size-4"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
              >
                <path d="M6 6l12 12M18 6L6 18" />
              </svg>
            </BaseDrawer.Close>
          )}
        </BaseDrawer.Popup>
      </BaseDrawer.Viewport>
    </BaseDrawer.Portal>
  );

  return keyboardAware && side === "bottom" ? (
    <BaseDrawer.VirtualKeyboardProvider>{portal}</BaseDrawer.VirtualKeyboardProvider>
  ) : (
    portal
  );
}

"use client";

import { createContext, useContext, useEffect, useState } from "react";
import { Drawer as BaseDrawer } from "@base-ui/react/drawer";

/* ---------- Types ---------- */

/** Edge a `Drawer` slides in from (physical: `left` and `right` never flip). */
export type DrawerSide = "bottom" | "top" | "left" | "right";
/** What the `side` prop accepts: a physical {@link DrawerSide}, or the logical `start` / `end`, which resolve against the text direction (`start` is the left edge in `ltr`, the right edge in `rtl`). */
export type DrawerSideProp = DrawerSide | "start" | "end";

/** Named snap heights for bottom sheets. */
export type DrawerSnapPreset = "peek" | "half" | "full";

/**
 * A snap height: a preset name, a fraction of the viewport height (0–1), a pixel number (> 1),
 * or a "px" / "rem" string such as "240px" or "18rem".
 */
export type DrawerSnapPoint = DrawerSnapPreset | number | (string & {});

/**
 * Every user-facing string of `Drawer` (accessible names, announcements, placeholders); pass a partial
 * `labels` prop to translate or reword them. Entries that need a count or a name are functions.
 */
export type DrawerLabels = {
  /** The × button. */
  close: string;
  /** Drag handle, when a taller snap point is available. */
  expand: string;
  /** Drag handle, at the tallest snap point. */
  collapse: string;
  /** Names of the preset heights: read out by the handle, and announced when it changes height. */
  snapPoints: Record<DrawerSnapPreset, string>;
  /** Name of a custom height (a number or "px" / "rem" snap point), 1-based from the smallest. */
  customSnapPoint: (position: number, count: number) => string;
  /** Read after the current height on the handle: how to change it. */
  handleHint: string;
};

/**
 * What `labels` accepts: any string, and any of the snap point names.
 *
 * @defaultLabels defaultDrawerLabels
 */
export type DrawerLabelsInput = Partial<Omit<DrawerLabels, "snapPoints">> & {
  snapPoints?: Partial<DrawerLabels["snapPoints"]>;
};

/**
 * Default English strings of `DrawerLabels`; spread it and override single keys to reword. Plain data
 * with no DOM access: safe to read while prerendering. The module is `"use client"`, so a React Server
 * Component receives a client reference instead of the object: read it from a client component.
 */
export const defaultDrawerLabels: DrawerLabels = {
  close: "Close",
  expand: "Expand sheet",
  collapse: "Collapse sheet",
  snapPoints: { peek: "Peek height", half: "Half height", full: "Full height" },
  customSnapPoint: (position, count) => `Height ${position} of ${count}`,
  handleHint: "Arrow keys change the height.",
};

/**
 * Starting values of the presets. Once the sheet is open, "peek" is measured from the content
 * (handle + header + first row of DrawerBody) and "half" is kept at least a row taller than peek.
 *
 * @see /overlays/drawer
 */
export const drawerSnapPresets: Record<DrawerSnapPreset, number | string> = {
  peek: "10rem",
  half: 0.5,
  full: 1,
};

/** The props of the underlying Base UI drawer root. @internal */
export type BaseRootProps = BaseDrawer.Root.Props;

/** Props of `Drawer`; each option is documented on its field. */
export type DrawerProps = Omit<
  BaseRootProps,
  "swipeDirection" | "snapPoints" | "snapPoint" | "defaultSnapPoint" | "onSnapPointChange"
> & {
  /**
   * The edge the drawer slides in from. It is also the direction a swipe dismisses it. Default "bottom". `"left"` and
   * `"right"` are physical and never flip; `"start"` and `"end"` follow the text direction (`<html dir>` or Base UI's
   * `DirectionProvider`): `"start"` is the left edge in `ltr` and the right edge in `rtl`.
   */
  side?: DrawerSideProp;
  /** Snap heights for a bottom sheet, smallest first. Ignored on other sides. */
  snapPoints?: readonly DrawerSnapPoint[];
  /** Controlled snap point (use with `onSnapPointChange`). */
  snapPoint?: DrawerSnapPoint | null;
  /** Snap point the sheet opens at. Defaults to the first one. */
  defaultSnapPoint?: DrawerSnapPoint | null;
  /**
   * Called when the snap point changes: by a drag (with Base UI's event details), or by the
   * handle button / keyboard / focus (no event details).
   */
  onSnapPointChange?: (
    snapPoint: DrawerSnapPoint | null,
    eventDetails?: BaseDrawer.Root.SnapPointChangeEventDetails,
  ) => void;
  /** Override any UI string (i18n). */
  labels?: DrawerLabelsInput;
};

/* ---------- Snap point helpers ---------- */

/** "half" stays at least this much taller than "peek" (about one list row). */
export const HALF_ABOVE_PEEK = 72;
/** The tallest a "first row" may be when measuring "peek". */
export const PEEK_ROW_MAX = 88;
/** Base UI keeps a sheet this far below the top of the screen at full height (--sheen-drawer-gap). */
export const FULL_GAP = 24;

/** The snap presets resolved to numbers or CSS lengths. @internal */
export type ResolvedPresets = Record<DrawerSnapPreset, number | string>;

/** True when a snap point is a named preset. @internal */
export function isPreset(value: DrawerSnapPoint): value is DrawerSnapPreset {
  return value === "peek" || value === "half" || value === "full";
}

/** Converts a snap point to the value Base UI expects. @internal */
export function toBaseSnapPoint(value: DrawerSnapPoint, presets: ResolvedPresets): number | string {
  return isPreset(value) ? presets[value] : value;
}

/** The root font size in pixels, for converting rem snap points. @internal */
export function rootFontSize() {
  if (typeof document === "undefined") return 16;
  return Number.parseFloat(getComputedStyle(document.documentElement).fontSize) || 16;
}

/** Height in px a Base UI snap value stands for (same rules as Base UI). */
export function toPx(value: number | string, viewport: number): number {
  if (typeof value === "number") return value <= 1 ? Math.max(0, value) * viewport : value;
  const amount = Number.parseFloat(value);
  if (!Number.isFinite(amount)) return 0;
  return value.trim().endsWith("rem") ? amount * rootFontSize() : amount;
}

/** The layout viewport height, kept current (snap heights are relative to it). */
export function useViewportHeight(enabled: boolean) {
  const [height, setHeight] = useState(0);
  useEffect(() => {
    if (!enabled) return;
    const measure = () => setHeight(window.innerHeight);
    measure();
    window.addEventListener("resize", measure);
    return () => window.removeEventListener("resize", measure);
  }, [enabled]);
  return height;
}

/* ---------- Context ---------- */

/** The state the drawer parts share. @internal */
export type DrawerContextValue = {
  side: DrawerSide;
  modal: BaseRootProps["modal"];
  labels: DrawerLabels;
  /** Snap points of a bottom sheet, smallest first, one per distinct height (empty otherwise). */
  orderedSnapPoints: DrawerSnapPoint[];
  /** Index of the current snap point in orderedSnapPoints (nearest height when not listed). */
  snapIndex: number;
  snapPoint: DrawerSnapPoint | null;
  setSnapPoint: (value: DrawerSnapPoint) => void;
  /** DrawerContent reports the measured "peek" height here. */
  setPeekHeight: (px: number) => void;
};

/** Shares the drawer state with its parts. @internal */
export const DrawerContext = createContext<DrawerContextValue | null>(null);

/** Reads the drawer context, throwing when used outside a drawer. @internal */
export function useDrawerContext(component: string) {
  const context = useContext(DrawerContext);
  if (!context) throw new Error(`SheenUI: <${component}> must be used inside <Drawer>.`);
  return context;
}

/** The swipe direction that dismisses a drawer on each side. @internal */
export const swipeDirections = { bottom: "down", top: "up", left: "left", right: "right" } as const;

"use client";

import { useEffect, useId, useRef, useState, type ComponentProps, type KeyboardEvent, type RefObject } from "react";
import { Drawer as BaseDrawer } from "@base-ui/react/drawer";

import { cn, classNameWith } from "../../lib/cn";
import { isPreset, useDrawerContext } from "./model";

/* ---------- Handle ---------- */

/**
 * The grab bar. It always drags the sheet; with snap points it is also a button that steps
 * through them (click / Enter / Space cycles, ArrowUp / ArrowDown step, Home / End jump).
 * It describes the current height to screen readers and announces the new one when it changes it.
 * Rendered by DrawerContent; export it only to place it yourself (`handle={false}` on the content).
 *
 * Keyboard: with two or more snap points it is a normal tab stop (see above). Accessibility: a labelled button
 * that reads the current height and how to change it, plus a polite status announcement. Without snap points it is a decorative bar.
 * Glass and motion: colour and scale transitions only; none under reduced motion beyond the colour change.
 *
 * @example
 * ```tsx
 * import { DrawerContent, DrawerHandle } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <DrawerContent handle={false}>
 *       <DrawerHandle className="mx-auto" />
 *     </DrawerContent>
 *   );
 * }
 * ```
 *
 * @see /overlays/drawer
 */
export function DrawerHandle({ className }: { className?: string }) {
  const { side, labels, orderedSnapPoints, snapIndex: index, setSnapPoint } = useDrawerContext("DrawerHandle");
  const count = orderedSnapPoints.length;
  const atTallest = index >= count - 1;
  const descriptionId = useId();
  const [announcement, setAnnouncement] = useState("");
  const interactive = count >= 2;

  const nameOf = (position: number) => {
    const point = orderedSnapPoints[position];
    if (point === undefined) return "";
    return isPreset(point) ? labels.snapPoints[point] : labels.customSnapPoint(position + 1, count);
  };

  const pill = (
    <span
      aria-hidden
      className={cn(
        "block h-1.5 w-10 rounded-sheen-full",
        "transition-[background-color,scale] duration-(--sheen-duration-fast) ease-sheen-out",
        // A button needs a 3:1 boundary; the purely decorative grabber can stay quieter.
        interactive
          ? "bg-sheen-control-border group-hover/handle:bg-sheen-fg-muted group-data-swiping/drawer:bg-sheen-fg-muted"
          : "bg-sheen-fg-subtle/55 group-data-swiping/drawer:bg-sheen-fg-subtle",
        // Grabbed: the bar stretches a little.
        "motion-ok:group-data-swiping/drawer:scale-x-125",
        "forced-colors:bg-[CanvasText]",
      )}
    />
  );

  const wrapper = cn("flex shrink-0 justify-center", side === "top" ? "pt-1 pb-2.5" : "pt-2.5 pb-1", className);

  if (!interactive) {
    return (
      <div data-slot="drawer-handle" className={wrapper}>
        <span className="flex h-5 w-16 items-center justify-center">{pill}</span>
      </div>
    );
  }

  function go(next: number) {
    const position = Math.max(0, Math.min(count - 1, next));
    const target = orderedSnapPoints[position];
    if (target === undefined) return;
    setSnapPoint(target);
    setAnnouncement(nameOf(position));
  }

  function handleKeyDown(event: KeyboardEvent<HTMLButtonElement>) {
    const keys: Record<string, () => void> = {
      ArrowUp: () => go(index + 1),
      ArrowRight: () => go(index + 1),
      ArrowDown: () => go(index - 1),
      ArrowLeft: () => go(index - 1),
      Home: () => go(0),
      End: () => go(count - 1),
    };
    const action = keys[event.key];
    if (!action) return;
    event.preventDefault();
    // Keep Base UI's composite key handling (and the page) from reacting too.
    event.stopPropagation();
    action();
  }

  return (
    <div data-slot="drawer-handle" className={wrapper}>
      <button
        type="button"
        aria-label={atTallest ? labels.collapse : labels.expand}
        aria-describedby={descriptionId}
        onClick={() => go(atTallest ? 0 : index + 1)}
        onKeyDown={handleKeyDown}
        className={cn(
          "group/handle relative flex h-5 w-16 cursor-grab items-center justify-center rounded-sheen-full active:cursor-grabbing",
          "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sheen-focus",
          // 44 px tall, 80 px wide hit area on touch screens.
          "any-pointer-coarse:after:absolute any-pointer-coarse:after:-inset-x-2 any-pointer-coarse:after:-inset-y-3",
        )}
      >
        {pill}
      </button>
      <span id={descriptionId} className="sr-only">
        {`${nameOf(index)}. ${labels.handleHint}`}
      </span>
      {/* Announces the new height after the handle changed it. */}
      <span role="status" className="sr-only">
        {announcement}
      </span>
    </div>
  );
}

/* ---------- Layout parts ---------- */

/**
 * Top section of the sheet: stacks the title and description, with room on the right for the × button.
 *
 * Keyboard: none. Accessibility: a plain `div`; the title and description inside name the dialog. Glass and motion: none.
 *
 * @example
 * ```tsx
 * import { DrawerDescription, DrawerHeader, DrawerTitle } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <DrawerHeader>
 *       <DrawerTitle>Filters</DrawerTitle>
 *       <DrawerDescription>Narrow the results.</DrawerDescription>
 *     </DrawerHeader>
 *   );
 * }
 * ```
 *
 * @see /overlays/drawer
 */
export function DrawerHeader({ className, ...props }: ComponentProps<"div">) {
  const { side } = useDrawerContext("DrawerHeader");
  return (
    <div
      data-slot="drawer-header"
      className={cn(
        "flex shrink-0 flex-col gap-1 px-5 pe-14",
        side === "bottom" ? "pt-2 pb-3" : side === "top" ? "pt-5 pb-3" : "pt-5 pb-4",
        className,
      )}
      {...props}
    />
  );
}

/**
 * The drawer's heading. It is the dialog's accessible name (`aria-labelledby` is wired for you).
 *
 * Keyboard: none. Accessibility: always render one, even if hidden visually with `className="sr-only"`. Glass and motion: none.
 *
 * @example
 * ```tsx
 * import { DrawerTitle } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <DrawerTitle>Filters</DrawerTitle>
 *   );
 * }
 * ```
 *
 * @see /overlays/drawer
 */
export function DrawerTitle({ className, ...props }: ComponentProps<typeof BaseDrawer.Title>) {
  return (
    <BaseDrawer.Title
      className={classNameWith(className, (extra) =>
        cn("text-lg leading-tight font-semibold tracking-tight text-balance", extra),
      )}
      {...props}
    />
  );
}

/**
 * Muted helper text under the title. It is the dialog's accessible description (`aria-describedby` is wired for you).
 *
 * Keyboard: none. Accessibility: keep it to a sentence. Glass and motion: none.
 *
 * @example
 * ```tsx
 * import { DrawerDescription } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <DrawerDescription>Narrow the results.</DrawerDescription>
 *   );
 * }
 * ```
 *
 * @see /overlays/drawer
 */
export function DrawerDescription({ className, ...props }: ComponentProps<typeof BaseDrawer.Description>) {
  return (
    <BaseDrawer.Description
      className={classNameWith(className, (extra) => cn("text-sm text-pretty text-sheen-fg-muted", extra))}
      {...props}
    />
  );
}

/**
 * The scrolling part of the sheet. Text in it can be selected with a mouse without dragging
 * the sheet, and touch scrolling hands over to swipe-to-dismiss at the scroll edge (Base UI).
 * It becomes a keyboard tab stop only while it actually overflows, so it can be scrolled with arrows.
 *
 * Keyboard: when it overflows, Tab focuses it and the arrow keys scroll. Accessibility: gets `tabIndex=0` only while scrollable, with an inset focus ring.
 * Glass and motion: flat; no motion of its own.
 *
 * @example
 * ```tsx
 * import { DrawerBody } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <DrawerBody>
 *       <p>Long content...</p>
 *     </DrawerBody>
 *   );
 * }
 * ```
 *
 * @see /overlays/drawer
 */
export function DrawerBody({ className, ...props }: ComponentProps<typeof BaseDrawer.Content>) {
  const ref = useRef<HTMLDivElement>(null);
  const scrollable = useOverflows(ref);
  return (
    <BaseDrawer.Content
      ref={ref}
      data-slot="drawer-body"
      tabIndex={scrollable ? 0 : undefined}
      className={classNameWith(className, (extra) =>
        cn(
          "min-h-0 flex-1 overflow-y-auto overscroll-contain px-5 py-2 touch-auto [scrollbar-width:thin]",
          "focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-sheen-focus",
          extra,
        ),
      )}
      {...props}
    />
  );
}

/**
 * Bottom row of actions, separated by a hairline: a column on phones (primary action first on screen) and a right-aligned row from `sm` up.
 *
 * Keyboard: none of its own. Accessibility: a plain `div`; the buttons inside are normal tab stops. Glass and motion: none.
 *
 * @example
 * ```tsx
 * import { Button, DrawerClose, DrawerFooter } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <DrawerFooter>
 *       <DrawerClose render={<Button variant="ghost">Cancel</Button>} />
 *       <Button>Apply</Button>
 *     </DrawerFooter>
 *   );
 * }
 * ```
 *
 * @see /overlays/drawer
 */
export function DrawerFooter({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      data-slot="drawer-footer"
      className={cn(
        "flex shrink-0 flex-col-reverse gap-2 border-t border-sheen-border px-5 pt-3 pb-4 sm:flex-row sm:justify-end",
        className,
      )}
      {...props}
    />
  );
}

/**
 * An invisible strip along a screen edge that opens the drawer with a swipe (touch screens).
 * Place it inside <Drawer>; it sits on the drawer's own side.
 *
 * Keyboard: none (touch only; keep a visible trigger as the keyboard route). Accessibility: not focusable and hidden from pointer-fine devices.
 * Glass and motion: invisible; the drawer follows the finger as it opens.
 *
 * @example
 * ```tsx
 * import { Drawer, DrawerContent, DrawerSwipeArea } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <Drawer side="left">
 *       <DrawerSwipeArea />
 *       <DrawerContent>...</DrawerContent>
 *     </Drawer>
 *   );
 * }
 * ```
 *
 * @see /overlays/drawer
 */
export function DrawerSwipeArea({ className, ...props }: ComponentProps<typeof BaseDrawer.SwipeArea>) {
  const { side } = useDrawerContext("DrawerSwipeArea");
  return (
    <BaseDrawer.SwipeArea
      className={classNameWith(className, (extra) =>
        cn(
          "fixed z-40 hidden any-pointer-coarse:block",
          {
            bottom: "inset-x-0 bottom-0 h-5",
            top: "inset-x-0 top-0 h-5",
            left: "inset-y-0 left-0 w-5",
            right: "inset-y-0 right-0 w-5",
          }[side],
          extra,
        ),
      )}
      {...props}
    />
  );
}

/* ---------- Hooks ---------- */

/** True while the element's content is taller than its box (re-checked as either changes). */
export function useOverflows(ref: RefObject<HTMLElement | null>) {
  const [overflows, setOverflows] = useState(false);
  useEffect(() => {
    const element = ref.current;
    if (!element || typeof ResizeObserver === "undefined") return;
    const measure = () => setOverflows(element.scrollHeight > element.clientHeight + 1);
    const resize = new ResizeObserver(measure);
    const observeAll = () => {
      resize.disconnect();
      resize.observe(element);
      for (const child of Array.from(element.children)) resize.observe(child);
      measure();
    };
    const mutations = new MutationObserver(observeAll);
    mutations.observe(element, { childList: true });
    observeAll();
    return () => {
      resize.disconnect();
      mutations.disconnect();
    };
  }, [ref]);
  return overflows;
}

/** Props of {@link DrawerTrigger}. The element that opens a `Drawer` (a `<button>` by default; use `render={<Button />}` for a SheenUI button). */
export type DrawerTriggerProps = ComponentProps<typeof BaseDrawer.Trigger>;

/** Props of {@link DrawerClose}. A button inside the drawer that closes it (a "Done" or "Cancel" action in `DrawerFooter`). */
export type DrawerCloseProps = ComponentProps<typeof BaseDrawer.Close>;

/** Props of {@link DrawerHandle}. The grab bar. */
export type DrawerHandleProps = ComponentProps<typeof DrawerHandle>;

/** Props of {@link DrawerHeader}. Top section of the sheet: stacks the title and description, with room on the right for the × button. */
export type DrawerHeaderProps = ComponentProps<typeof DrawerHeader>;

/** Props of {@link DrawerTitle}. The drawer's heading. */
export type DrawerTitleProps = ComponentProps<typeof DrawerTitle>;

/** Props of {@link DrawerDescription}. Muted helper text under the title. */
export type DrawerDescriptionProps = ComponentProps<typeof DrawerDescription>;

/** Props of {@link DrawerBody}. The scrolling part of the sheet. */
export type DrawerBodyProps = ComponentProps<typeof DrawerBody>;

/** Props of {@link DrawerFooter}. Bottom row of actions, separated by a hairline: a column on phones (primary action first on screen) and a right-aligned row from `sm` up. */
export type DrawerFooterProps = ComponentProps<typeof DrawerFooter>;

/** Props of {@link DrawerSwipeArea}. An invisible strip along a screen edge that opens the drawer with a swipe (touch screens). */
export type DrawerSwipeAreaProps = ComponentProps<typeof DrawerSwipeArea>;

"use client";

import { createContext, useCallback, useContext, useEffect, useRef, type PointerEvent, type RefObject } from "react";

import { cn } from "../../lib/cn";
import { PHONE_QUERY, useMediaQuery } from "../../hooks/use-media-query";

/**
 * How an overlay presents itself on a phone-width screen (`max-width: 640px`).
 *
 * - `"popup"`: the same floating panel as everywhere else.
 * - `"sheet"`: a bottom sheet: full width, a drag handle, swipe down to dismiss, height capped in `dvh` with the content
 *   scrolling inside, padded past the home indicator.
 */
export type MobilePresentation = "popup" | "sheet";

/**
 * True when `mobile` asks for a sheet and the viewport is phone-width. `false` on the server and during hydration, so markup never mismatches.
 *
 * @internal
 */
export function useSheetMode(mobile: MobilePresentation | undefined) {
  const phone = useMediaQuery(PHONE_QUERY, { enabled: mobile === "sheet" });
  return mobile === "sheet" && phone;
}

const SheetContext = createContext(false);

/**
 * Provides whether the overlay root above is presenting as a sheet. The root wrappers (Dialog, Popover, Menu) render it.
 *
 * @internal
 */
export const SheetProvider = SheetContext;

/**
 * True inside an overlay root that is presenting as a bottom sheet right now.
 *
 * @internal
 */
export function useIsSheet() {
  return useContext(SheetContext);
}

/** The imperative handle every Base UI overlay root exposes through `actionsRef`; `close` goes through `onOpenChange`. */
export type SheetActions = { close: () => void; unmount: () => void };

const SheetActionsContext = createContext<RefObject<SheetActions | null> | null>(null);

/**
 * Hands the overlay root's `actionsRef` to the sheet handle below it, so a swipe closes the overlay through the
 * primitive's own open-change path.
 *
 * @internal
 */
export const SheetActionsProvider = SheetActionsContext;

/**
 * The `actionsRef` to give a Base UI root: the caller's own when it passed one, else a private one.
 *
 * @internal
 */
export function useSheetActionsRef(own?: RefObject<SheetActions | null>): RefObject<SheetActions | null> {
  const fallback = useRef<SheetActions | null>(null);
  return own ?? fallback;
}

/**
 * Classes of the fixed element Base UI positions around a popup, turned into a full-width strip on the bottom edge.
 *
 * @internal
 */
export const sheetPositionerClass =
  "fixed! inset-x-0! top-auto! bottom-0! left-0! z-50 w-full! max-w-none! translate-none! transform-none! outline-none";

/**
 * The dimmed scrim behind a sheet (Base UI's `Backdrop` of each overlay).
 *
 * @internal
 */
export const sheetBackdropClass = cn(
  "fixed inset-0 z-50 min-h-dvh bg-sheen-scrim",
  "transition-opacity duration-(--sheen-duration-base) ease-sheen-out motion-reduced:duration-(--sheen-duration-fast)",
  "data-starting-style:opacity-0",
  "data-ending-style:opacity-0 data-ending-style:duration-(--sheen-duration-exit) data-ending-style:ease-sheen-exit",
);

/**
 * The sheet itself (replaces the popup's own placement and motion): the strong glass slides up from the edge, follows a
 * finger (`--sheen-sheet-drag`, set by {@link useSheetSwipe}), leaves with a shorter ease-in. Reduced motion: no sliding,
 * a plain fade.
 *
 * @internal
 */
export const sheetPopupClass = cn(
  "relative w-full! max-w-none! rounded-b-none! rounded-t-sheen-xl border-b-0 outline-none",
  "max-h-[min(85dvh,calc(100dvh-2rem))]! overflow-y-auto overscroll-contain",
  // Padding model: the popup states its own inline and block-end padding as `--sheen-sheet-px` / `--sheen-sheet-pb` (and
  // its own top padding with `pt-*`; defaults 0 and 0.5rem). The home-indicator inset is added below the content; the side insets (landscape
  // notches) only matter when they are larger than the popup's own padding. Both sides are symmetric, so RTL is the same.
  "pr-[max(var(--sheen-sheet-px,0px),env(safe-area-inset-right))] pl-[max(var(--sheen-sheet-px,0px),env(safe-area-inset-left))]",
  "pb-[calc(var(--sheen-sheet-pb,0.5rem)+env(safe-area-inset-bottom))]",
  "[transform:translateY(var(--sheen-sheet-drag,0px))]",
  "[transition:transform_var(--sheen-duration-smooth)_var(--sheen-ease-smooth),opacity_var(--sheen-duration-base)_var(--sheen-ease-out)]",
  "motion-ok:data-starting-style:[transform:translateY(calc(100%+2px))]",
  "data-ending-style:[transition:transform_var(--sheen-duration-exit-panel,calc(var(--sheen-duration-exit)*1.5))_var(--sheen-ease-exit),opacity_var(--sheen-duration-exit)_var(--sheen-ease-exit)]",
  // A sheet dragged past its own height (a short one) keeps going from where the finger left it, never back up to the edge.
  "motion-ok:data-ending-style:[transform:translateY(max(calc(100%+2px),var(--sheen-sheet-drag,0px)))]",
  "motion-reduced:data-starting-style:opacity-0 motion-reduced:data-ending-style:opacity-0",
  // While a finger holds it, it follows with no easing.
  "data-dragging:[transition:none]",
  "after:pointer-events-none after:absolute after:-inset-x-px after:top-full after:h-16 after:bg-[inherit] after:content-['']",
);

const DISMISS_DISTANCE = 96;
const DISMISS_VELOCITY = 0.6;
/** Pointer travel (px) below which a press on the handle is a tap, not a drag. */
const TAP_SLOP = 6;
/** Frames to wait for a closing overlay to enter its exit before treating the dismiss as vetoed. */
const SETTLE_FRAMES = 4;

/**
 * Swipe-to-dismiss for a sheet drawn from a floating-popup primitive (Select, Menu, Popover, Dialog). Spread the result
 * on the drag handle: the sheet follows the finger and, past a third of the way or on a fast flick, closes the overlay
 * through the root's `close` action (so `onOpenChange` still sees the dismiss and can veto it). Released early, it springs back.
 * @internal
 */
export function useSheetSwipe(popupRef: RefObject<HTMLElement | null>, actionsRef?: RefObject<SheetActions | null>) {
  const fromContext = useContext(SheetActionsContext);
  const actions = actionsRef ?? fromContext;
  const settle = useRef(0);
  const drag = useRef<{ id: number; startY: number; startAt: number; dy: number } | null>(null);
  const dragged = useRef(false);

  const setOffset = useCallback(
    (px: number | null) => {
      const popup = popupRef.current;
      if (!popup) return;
      if (px === null) {
        popup.style.removeProperty("--sheen-sheet-drag");
        popup.removeAttribute("data-dragging");
      } else {
        popup.style.setProperty("--sheen-sheet-drag", `${px}px`);
        popup.setAttribute("data-dragging", "");
      }
    },
    [popupRef],
  );

  useEffect(
    () => () => {
      cancelAnimationFrame(settle.current);
      setOffset(null);
    },
    [setOffset],
  );

  return {
    onPointerDown(event: PointerEvent<HTMLElement>) {
      if (event.pointerType === "mouse" && event.button !== 0) return;
      try {
        event.currentTarget.setPointerCapture(event.pointerId);
      } catch {
        /* a synthetic pointer has nothing to capture */
      }
      dragged.current = false;
      drag.current = { id: event.pointerId, startY: event.clientY, startAt: event.timeStamp, dy: 0 };
    },
    onPointerMove(event: PointerEvent<HTMLElement>) {
      const state = drag.current;
      if (state?.id !== event.pointerId) return;
      state.dy = Math.max(0, event.clientY - state.startY);
      if (Math.abs(event.clientY - state.startY) > TAP_SLOP) dragged.current = true;
      setOffset(state.dy);
    },
    onPointerUp(event: PointerEvent<HTMLElement>) {
      const state = drag.current;
      if (state?.id !== event.pointerId) return;
      drag.current = null;
      const popup = popupRef.current;
      const height = popup?.getBoundingClientRect().height ?? 0;
      const velocity = state.dy / Math.max(1, event.timeStamp - state.startAt);
      const dismiss =
        state.dy > Math.min(DISMISS_DISTANCE, height / 3) || (state.dy > 24 && velocity > DISMISS_VELOCITY);
      if (dismiss && popup) {
        // The overlay closes through its own dismiss path; its exit animation continues from the dragged position.
        popup.removeAttribute("data-dragging");
        actions?.current?.close();
        // Some roots (Popover) start their exit a frame or two after `close()`. Only when the overlay is still open after
        // that (the app vetoed it) does the sheet settle back; otherwise the exit carries on in the drag direction, never up.
        let frames = 0;
        const check = () => {
          const left =
            !popup.isConnected || popup.hasAttribute("data-ending-style") || popup.hasAttribute("data-closed");
          if (left) return;
          if (++frames < SETTLE_FRAMES) settle.current = requestAnimationFrame(check);
          else setOffset(null);
        };
        settle.current = requestAnimationFrame(check);
      } else {
        setOffset(null);
      }
    },
    /** A tap, Enter or Space on the handle closes the sheet through the same vetoable path as a swipe; the click that ends a drag is not a tap. */
    onClick() {
      if (dragged.current) {
        dragged.current = false;
        return;
      }
      actions?.current?.close();
    },
    onPointerCancel(event: PointerEvent<HTMLElement>) {
      if (drag.current?.id !== event.pointerId) return;
      drag.current = null;
      setOffset(null);
    },
  };
}

/**
 * The grab handle of a sheet: a real button (44 px tall hit area) named by the overlay's `labels.close`. Tap, click,
 * Enter or Space close the overlay and dragging it down dismisses it ({@link useSheetSwipe}); both go through the root's
 * own `close` action, so `onOpenChange` can veto them.
 *
 * @internal
 */
export function SheetHandle({
  popupRef,
  actionsRef,
  label,
  redundant = false,
}: {
  popupRef: RefObject<HTMLElement | null>;
  actionsRef?: RefObject<SheetActions | null>;
  /** Accessible name of the handle (the overlay's `labels.close`). */
  label: string;
  /**
   * The sheet already has a visible, named close button (a Dialog's ×): the handle then stays a touch target but is
   * hidden from assistive technology, so the sheet has exactly one "Close" to find.
   */
  redundant?: boolean;
}) {
  const swipe = useSheetSwipe(popupRef, actionsRef);
  return (
    <button
      type="button"
      aria-label={redundant ? undefined : label}
      aria-hidden={redundant || undefined}
      // Out of the Tab order on purpose: the overlay's own initial focus (a Select's highlighted option, a Dialog's first field)
      // must not land on the handle. Escape and the overlay's own controls are the keyboard way out; assistive technology
      // and touch operate the handle directly.
      tabIndex={-1}
      data-slot="sheet-handle"
      className="group sticky top-0 z-10 -mb-2 flex h-11 w-full shrink-0 cursor-grab touch-none items-start justify-center bg-transparent pt-1.5 select-none focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-sheen-focus active:cursor-grabbing"
      {...swipe}
    >
      <span className="flex h-6 w-16 items-center justify-center">
        <span className="block h-1.5 w-10 rounded-sheen-full bg-sheen-fg-subtle/55 forced-colors:bg-[CanvasText]" />
      </span>
    </button>
  );
}

